package com.android.tools.lint.checks;

imports static SdkConstants.

public class AndroidTvDetector extends Detector implements Detector.XmlScanner {

private static final Map<String, List<String>> IMPLIED_FEATURES;

static {
Map<String, List<String>> map = new HashMap<>();
map.put(PERMISSION_CAMERA, Arrays.asList(FEATURE_CAMERA, FEATURE_CAMERA_AUTOFOCUS));
map.put(PERMISSION_RECORD_AUDIO, Collections.singletonList(FEATURE_MICROPHONE));
map.put(PERMISSION_ACCESS_FINE_LOCATION, Arrays.asList(FEATURE_LOCATION, FEATURE_LOCATION_GPS));
map.put(PERMISSION_ACCESS_COARSE_LOCATION, Arrays.asList(FEATURE_LOCATION, FEATURE_LOCATION_NETWORK));
map.put(PERMISSION_CALL_PHONE, Collections.singletonList(FEATURE_TELEPHONY));
map.put(PERMISSION_READ_PHONE_STATE, Collections.singletonList(FEATURE_TELEPHONY));
map.put(PERMISSION_SEND_SMS, Collections.singletonList(FEATURE_TELEPHONY));
map.put(PERMISSION_RECEIVE_SMS, Collections.singletonList(FEATURE_TELEPHONY));
map.put(PERMISSION_READ_SMS, Collections.singletonList(FEATURE_TELEPHONY));
map.put(PERMISSION_RECEIVE_WAP_PUSH, Collections.singletonList(FEATURE_TELEPHONY));
map.put(PERMISSION_RECEIVE_MMS, Collections.singletonList(FEATURE_TELEPHONY));
map.put(PERMISSION_BODY_SENSORS, Collections.singletonList(FEATURE_SENSOR_HEART_RATE));
IMPLIED_FEATURES = Collections.unmodifiableMap(map);
}

public static final Issue ISSUE = Issue.create(... Category.TV ...);

@Override
public Collection<String> getApplicableElements() {
return Collections.singletonList(TAG_USES_PERMISSION);
}

@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
String permission = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
if (permission == null || permission.isEmpty()) return;
List<String> features = IMPLIED_FEATURES.get(permission);
if (features == null) return;

// Build set of declared features and whether required false.
Map<String, Boolean> declaredFeatures = new HashMap<>();
NodeList featuresList = element.getOwnerDocument().getElementsByTagName(TAG_USES_FEATURE);
for (int i=0; i<featuresList.getLength(); i++) {
Element feature = (Element) featuresList.item(i);
String name = feature.getAttributeNS(ANDROID_URI, ATTR_NAME);
String required = feature.getAttributeNS(ANDROID_URI, ATTR_REQUIRED);
boolean requiredFalse = "false".equals(required);
declaredFeatures.put(name, requiredFalse);
}

List<String> missing = new ArrayList<>();
for (String feature : features) {
Boolean requiredFalse = declaredFeatures.get(feature);
if (requiredFalse == null || !requiredFalse) {
missing.add(feature);
}
}
if (!missing.isEmpty()) {
String message = "Permission `"+permission+"` implies hardware feature(s) "+missing+" which are not supported on TVs. Consider adding `<uses-feature android:name=\"...\" android:required=\"false\" />.";
context.report(ISSUE, element, context.getLocation(element), message);
}
}

